#[cfg(feature = "fuse")]
pub(crate) fn poll_filepointer_resolution(
    fs: &mut crate::CipherBoxFS,
    ino: u64,
) -> PollResult {
    use std::time::Duration;
    const FILEPOINTER_POLL_TIMEOUT: Duration = Duration::from_secs(5);
